where.if:
AND EXISTS (
    SELECT 1
      FROM TB_ORD_ITEM I
      JOIN TB_PRD P ON P.PRD_CD = I.PRD_CD
     WHERE I.ORD_NO = O.ORD_NO
    AND I.PRD_CD = #{PRD_CD}
    AND P.PRD_NM LIKE '%' || #{PRD_NM} || '%'
    AND I.SELLER_ID = #{SELLER_ID}
)

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT , (SELECT M.MBR_NM FROM TB_MBR M WHERE M.MBR_ID = O.MBR_ID) AS MBR_NM, (SELECT COUNT(*) FROM TB_ORD_ITEM I WHERE I.ORD_NO = O.ORD_NO) AS ITEM_CNT, (SELECT P.PRD_NM FROM TB_ORD_ITEM I JOIN TB_PRD P ON P.PRD_CD = I.PRD_CD WHERE I.ORD_NO = O.ORD_NO AND I.ITEM_SEQ = 1) AS REP_PRD_NM, (SELECT Y.PAY_MTHD FROM TB_PAY Y WHERE Y.ORD_NO = O.ORD_NO AND ROWNUM = 1) AS PAY_MTHD, (SELECT D.DLV_STAT FROM TB_DLV D WHERE D.ORD_NO = O.ORD_NO AND ROWNUM = 1) AS DLV_STAT, 'N' AS CHK FROM TB_ORD O
ORDER BY O.PAY_AMT DESC, O.ORD_NO DESC ORDER BY O.ORD_DT DESC, O.ORD_NO DESC
) A WHERE ROWNUM <= #{PAGE_NO} * #{PAGE_SIZE} ) WHERE RNUM > (#{PAGE_NO} - 1) * #{PAGE_SIZE}

SELECT ORD_NO, ITEM_SEQ, PRD_CD, SELLER_ID, QTY, UNIT_PRC, ITEM_AMT, ITEM_STAT
  FROM TB_ORD_ITEM
 WHERE ORD_NO = #{ORD_NO}
   AND ITEM_SEQ = #{ITEM_SEQ}

mapper.update:
UPDATE TB_ORD
   SET ORD_STAT = #{AF_STAT}
     , PAY_DT = NVL(PAY_DT, SYSDATE)
     , CNFM_DT = SYSDATE, CNFM_TYPE = #{CNFM_TYPE}
     , CNCL_DT = SYSDATE
     , CNCL_RSN = #{CNCL_RSN}
     , UPD_DT = SYSDATE
     , UPD_ID = #{CHG_ID}
 WHERE ORD_NO = #{ORD_NO}

mapper.insert:

  SELECT NVL(MAX(HIST_SEQ), 0) + 1 FROM TB_ORD_STAT_HIST WHERE ORD_NO = #{ORD_NO}

INSERT INTO TB_ORD_STAT_HIST (ORD_NO, HIST_SEQ, BF_STAT, AF_STAT, CHG_RSN, CHG_DT, CHG_ID)
VALUES (#{ORD_NO}, #{HIST_SEQ}, #{BF_STAT}, #{AF_STAT}, SUBSTRB(#{CHG_RSN}, 1, 200), SYSDATE, NVL(#{CHG_ID}, 'SYSTEM'))

mapper.update:
UPDATE TB_ORD_ITEM
   SET ITEM_STAT = #{ITEM_STAT}
     , CNCL_DT = NVL(CNCL_DT, SYSDATE)
     , UPD_DT = SYSDATE
 WHERE ORD_NO = #{ORD_NO}

   AND ITEM_SEQ = #{ITEM_SEQ}


   AND ITEM_STAT = #{BF_ITEM_STAT}

UPDATE TB_ORD_ITEM
   SET ITEM_STAT        = 'C'
     , CPN_DC_SHARE_AMT = #{CPN_DC_SHARE_AMT}
     , PNT_SHARE_AMT    = #{PNT_SHARE_AMT}
     , REFUND_AMT       = #{REFUND_AMT}
     , CNCL_DT          = SYSDATE
     , UPD_DT           = SYSDATE
 WHERE ORD_NO   = #{ORD_NO}
   AND ITEM_SEQ = #{ITEM_SEQ}
   AND ITEM_STAT = 'N'

UPDATE TB_ORD
   SET CNCL_AMT = CNCL_AMT + #{ADD_CNCL_AMT}
     , UPD_DT   = SYSDATE
     , UPD_ID   = #{CHG_ID}
 WHERE ORD_NO = #{ORD_NO}
